    """Split a cent total into n integer parts that sum exactly to total.

    The parts differ by at most 1 cent. For positive totals, any remainder is
    distributed by adding 1 cent to the first `remainder` parts. For negative
    totals, the split mirrors the positive case (same positions, negated).
    """
    if not isinstance(total, int):
        raise TypeError("total must be an integer number of cents")
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n <= 0:
        raise ValueError("n must be greater than 0")

    if total < 0:
        return [-p for p in split_cents(-total, n)]

    base, remainder = divmod(total, n)
    return [base + 1] * remainder + [base] * (n - remainder)
